contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address logFileArg) public {
        bool firstCallReverted;
        c.SetLogFile(logFileArg); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstCallReverted = true;
        } else {
            firstCallReverted = false;
        }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool secondCallReverted;
        c.SetLogFile(logFileArg); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondCallReverted = true;
        } else {
            secondCallReverted = false;
        }

        assert(!firstCallReverted && secondCallReverted);
    }
}

