// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(address logFileArg) internal {
        bool firstCallReverted;
        try c.SetLogFile(logFileArg) {
            firstCallReverted = false;
        } catch {
            firstCallReverted = true;
        }
        try c.Initialized() {} catch { return; }
        bool secondCallReverted;
        try c.SetLogFile(logFileArg) {
            secondCallReverted = false;
        } catch {
            secondCallReverted = true;
        }
        assertTrue(!firstCallReverted && secondCallReverted);
    }

    function testFuzz_run(address logFileArg) public {
        vm.assume(logFileArg.code.length == 0 && uint160(logFileArg) > 0xffff && logFileArg != address(this) && logFileArg != address(c) && logFileArg != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logFileArg != 0x000000000000000000636F6e736F6c652e6c6f67 && logFileArg != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logFileArg != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(logFileArg);
    }

    receive() external payable {}
}
